changeSet.sql:
DO $post$
DECLARE
    n         int;
    n_gated   int;
    n_sql     int;
BEGIN
    SELECT count(*),
           count(*) FILTER (WHERE p.prosrc LIKE '%nexus.lexical_trgm%' AND p.prosrc LIKE '%~~*%'),
           count(*) FILTER (WHERE p.prolang = (SELECT l.oid FROM pg_catalog.pg_language l WHERE l.lanname = 'sql')
                              AND NOT p.prosecdef AND p.proconfig IS NULL)
      INTO n, n_gated, n_sql
      FROM pg_catalog.pg_proc p
     WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace
       AND p.proname IN ('text_gated_search_hnsw_first_384', 'text_gated_search_hnsw_first_768', 'text_gated_search_hnsw_first_1024', 'text_gated_search_allowed_384', 'text_gated_search_allowed_768', 'text_gated_search_allowed_1024', 'manifest_search_384', 'manifest_search_768', 'manifest_search_1024', 'manifest_qualifying_hits');
    IF n <> 10 OR n_gated <> 10 OR n_sql <> 10 THEN
        RAISE EXCEPTION 'vectors-058-2: expected 10 gate functions, one signature each, each reading nexus.lexical_trgm, LANGUAGE sql SECURITY INVOKER with no SET (inlinable); found % / % / %', n, n_gated, n_sql;
    END IF;
END
$post$;
